-- ════════════════════════════════════════════════════════════════════════════
--  ENTRE NÓS TARÔ — FASE 1: CATÁLOGO DAS 78 CARTAS (RIDER-WAITE-SMITH)
--
--  Cadastra as 78 cartas de referência em public.tarot_cards: 22 arcanos
--  maiores (numeração RWS, com Força em 8 e Justiça em 11) e 56 arcanos
--  menores (14 por naipe: wands, cups, swords, pentacles).
--
--  Conteúdo interpretativo (palavras-chave e significados em português) é
--  redação original, sem cópia de fontes externas. Nenhuma carta afirma
--  morte, gravidez, doença, crime ou traição como fato — a linguagem é
--  sempre de possibilidade, nunca de certeza absoluta, e não substitui
--  aconselhamento médico, jurídico ou financeiro.
--
--  image_path fica NULL nesta etapa (será preenchido quando as imagens
--  existirem). active = true em todas as 78 linhas.
--
--  Idempotente: pode ser reaplicada com segurança — ON CONFLICT (canonical_name)
--  atualiza os campos de conteúdo sem duplicar linhas nem alterar id/created_at.
--
--  Não aplicada a nenhum projeto Supabase por este script — apenas o arquivo
--  de migration, pronto para revisão manual.
-- ════════════════════════════════════════════════════════════════════════════

insert into public.tarot_cards
  (canonical_name, arcana, suit, card_number, upright_keywords, reversed_keywords,
   upright_meaning, reversed_meaning, image_path, active)
values
  ('The Fool', 'major', null, 0, ARRAY['início', 'espontaneidade', 'fé no caminho', 'liberdade', 'salto de coragem']::text[], ARRAY['imprudência', 'hesitação excessiva', 'risco mal calculado', 'dispersão', 'medo de começar']::text[], 'O Louco representa o primeiro passo de uma jornada ainda sem mapa. Convida a confiar no movimento antes de ter todas as respostas, abraçando a novidade com leveza e coragem, mesmo sem garantias do que vem a seguir.', 'Nesta posição, o Louco fala de impulsividade sem preparo ou, ao contrário, de um medo tão grande que trava qualquer início. Pode ser hora de avaliar riscos com mais cuidado antes de dar o próximo passo.', null, true),
  ('The Magician', 'major', null, 1, ARRAY['ação consciente', 'recursos disponíveis', 'vontade direcionada', 'habilidade', 'manifestação']::text[], ARRAY['dispersão de energia', 'manipulação', 'potencial não usado', 'insegurança', 'falta de foco']::text[], 'O Mago mostra que os recursos necessários já estão ao alcance das mãos. É tempo de unir intenção clara e ação prática, transformando ideias em resultados concretos através de foco e confiança na própria capacidade.', 'Invertido, o Mago aponta para talentos que não estão sendo bem aproveitados, seja por dispersão, insegurança ou uso da própria habilidade de forma pouco honesta. Vale reorganizar a intenção antes de agir novamente.', null, true),
  ('The High Priestess', 'major', null, 2, ARRAY['intuição', 'silêncio interior', 'mistério', 'sabedoria não dita', 'espera consciente']::text[], ARRAY['desconexão interior', 'segredos revelados', 'confusão emocional', 'negação da intuição', 'ruído externo']::text[], 'A Sacerdotisa convida a ouvir a intuição antes de qualquer resposta externa. Nem tudo precisa ser explicado ou decidido agora — há sabedoria em permanecer em silêncio e deixar que a clareza amadureça por dentro.', 'Quando invertida, essa carta sugere afastamento da própria voz interior, seja por excesso de ruído externo ou por ignorar sinais sutis. Segredos podem vir à tona antes do tempo que se imaginava.', null, true),
  ('The Empress', 'major', null, 3, ARRAY['fertilidade', 'abundância', 'cuidado', 'criatividade', 'conexão com a natureza']::text[], ARRAY['bloqueio criativo', 'autocuidado esquecido', 'dependência excessiva', 'estagnação', 'excesso de exigência consigo']::text[], 'A Imperatriz representa fartura, criatividade e cuidado que nutrem o que está crescendo — um projeto, uma relação ou a própria vida. É tempo de florescer com paciência, permitindo que as coisas se desenvolvam em seu próprio ritmo.', 'Invertida, pode indicar autocuidado deixado de lado, criatividade bloqueada ou uma relação de dependência que cansa mais do que nutre. É um convite para retomar contato com o que realmente sustenta o bem-estar.', null, true),
  ('The Emperor', 'major', null, 4, ARRAY['estrutura', 'autoridade', 'estabilidade', 'disciplina', 'proteção']::text[], ARRAY['rigidez excessiva', 'autoritarismo', 'falta de controle', 'insegurança disfarçada', 'resistência à mudança']::text[], 'O Imperador fala de ordem, estrutura e liderança firme. É momento de estabelecer limites claros, assumir responsabilidade e construir uma base sólida sobre a qual outras conquistas poderão se apoiar com segurança.', 'Invertido, alerta para rigidez excessiva ou, no outro extremo, ausência de estrutura onde ela seria necessária. Pode também indicar autoridade exercida de forma dura demais, afastando quem deveria ser apoiado.', null, true),
  ('The Hierophant', 'major', null, 5, ARRAY['tradição', 'orientação', 'aprendizado formal', 'valores compartilhados', 'pertencimento']::text[], ARRAY['questionamento de regras', 'rebeldia', 'dogmatismo', 'caminho próprio', 'ruptura com convenções']::text[], 'O Hierofante representa tradição, ensino e valores compartilhados que dão suporte à caminhada. Pode indicar a busca por orientação em uma fonte confiável, ou o desejo de pertencer a algo maior do que si mesmo.', 'Nesta posição, sugere a necessidade de questionar regras ou tradições que já não fazem sentido. Pode ser hora de trilhar um caminho mais próprio, mesmo que isso signifique romper com expectativas estabelecidas.', null, true),
  ('The Lovers', 'major', null, 6, ARRAY['conexão verdadeira', 'escolha do coração', 'harmonia', 'valores alinhados', 'vínculo']::text[], ARRAY['desalinhamento de valores', 'indecisão', 'desconexão afetiva', 'conflito de escolhas', 'insegurança na relação']::text[], 'Os Enamorados falam de conexão genuína e escolhas guiadas pelo coração. Pode representar um relacionamento significativo ou uma decisão importante que exige alinhar valores pessoais com o caminho que se deseja seguir.', 'Invertida, aponta para desequilíbrio em uma escolha ou relação, indecisão diante de caminhos importantes, ou valores que não estão mais alinhados entre as partes envolvidas. Pede reflexão antes de seguir adiante.', null, true),
  ('The Chariot', 'major', null, 7, ARRAY['determinação', 'foco', 'superação', 'avanço', 'autocontrole']::text[], ARRAY['falta de direção', 'dispersão de esforços', 'conflito interno', 'impulsividade descontrolada', 'estagnação forçada']::text[], 'O Carro representa força de vontade e avanço decidido, mesmo diante de forças opostas. É tempo de manter o foco em um objetivo, unindo disciplina e confiança para seguir em frente sem se dispersar.', 'Invertido, sugere perda de direção ou esforços puxando para lados opostos. Pode ser sinal de impulsividade sem controle, ou de um momento em que avançar exige antes reorganizar as próprias prioridades.', null, true),
  ('Strength', 'major', null, 8, ARRAY['coragem gentil', 'domínio emocional', 'paciência', 'resiliência', 'força interior']::text[], ARRAY['autocrítica excessiva', 'insegurança', 'perda de paciência', 'força mal direcionada', 'exaustão emocional']::text[], 'A Força fala de coragem exercida com gentileza, não com dureza. Mostra que é possível lidar com desafios difíceis através de paciência, compaixão consigo mesmo e uma resiliência que não precisa gritar para ser real.', 'Invertida, pode indicar autocrítica excessiva, insegurança diante de um desafio ou paciência que já se esgotou. É um convite para tratar a si mesmo com mais gentileza antes de seguir adiante.', null, true),
  ('The Hermit', 'major', null, 9, ARRAY['introspecção', 'busca interior', 'solitude escolhida', 'sabedoria pessoal', 'pausa reflexiva']::text[], ARRAY['isolamento excessivo', 'solidão não escolhida', 'resistência a orientação', 'confusão interior', 'afastamento prolongado']::text[], 'O Eremita convida a um momento de recolhimento consciente, afastado do ruído externo, para buscar respostas que só existem em silêncio. É tempo de refletir antes de agir, guiado pela própria luz interior.', 'Nesta posição, pode sinalizar isolamento que já passou do ponto de ser saudável, ou resistência em buscar apoio quando ele seria bem-vindo. Vale observar se a solitude ainda está servindo ao crescimento.', null, true),
  ('Wheel of Fortune', 'major', null, 10, ARRAY['ciclos', 'mudança inevitável', 'oportunidade', 'movimento da vida', 'virada']::text[], ARRAY['resistência à mudança', 'sensação de azar', 'ciclo repetitivo', 'perda de oportunidade', 'instabilidade']::text[], 'A Roda da Fortuna fala de ciclos que se movem por conta própria, trazendo mudanças que fogem do controle direto. Pode indicar uma virada favorável se aproximando, lembrando que tudo na vida é passageiro.', 'Invertida, sugere resistência a uma mudança necessária ou a sensação de estar preso em um ciclo que se repete. Pode ser hora de soltar o controle e permitir que as coisas sigam seu curso.', null, true),
  ('Justice', 'major', null, 11, ARRAY['equilíbrio', 'verdade', 'responsabilidade', 'decisão justa', 'consequências claras']::text[], ARRAY['injustiça percebida', 'desonestidade', 'desequilíbrio', 'evasão de responsabilidade', 'decisão adiada']::text[], 'A Justiça representa equilíbrio, verdade e a necessidade de assumir responsabilidade pelas próprias escolhas. Indica um momento de decisões justas, onde causa e efeito se mostram com clareza e pedem honestidade.', 'Invertida, pode apontar para uma sensação de injustiça, desonestidade em jogo, ou responsabilidade sendo evitada. Também pode indicar uma decisão importante sendo adiada além do que seria saudável.', null, true),
  ('The Hanged Man', 'major', null, 12, ARRAY['pausa consciente', 'novo ponto de vista', 'entrega', 'suspensão', 'aceitação']::text[], ARRAY['resistência à pausa', 'estagnação frustrada', 'sacrifício desnecessário', 'vitimização', 'atraso prolongado']::text[], 'O Enforcado fala de uma pausa necessária, um momento de ver a situação sob um ângulo completamente diferente. Convida a soltar o controle e aceitar que, às vezes, não agir é a atitude mais sábia.', 'Invertido, sugere resistência a uma pausa necessária, gerando estagnação e frustração. Pode também indicar sacrifícios feitos sem propósito real, ou a sensação de estar preso em um atraso que incomoda.', null, true),
  ('Death', 'major', null, 13, ARRAY['transformação', 'encerramento', 'renovação', 'fim de ciclo', 'transição']::text[], ARRAY['resistência à mudança', 'apego ao passado', 'transição incompleta', 'medo do fim', 'estagnação']::text[], 'A Morte simboliza o fim necessário de um ciclo para que outro possa começar. Não fala de tragédia, mas de transformação profunda — soltar o que já cumpriu seu propósito para abrir espaço ao novo.', 'Invertida, indica resistência a um encerramento necessário, apego ao que já não serve mais, ou uma transição que começou mas não foi completada. O medo de soltar pode estar prolongando o desconforto.', null, true),
  ('Temperance', 'major', null, 14, ARRAY['equilíbrio', 'moderação', 'paciência', 'integração', 'harmonia entre opostos']::text[], ARRAY['desequilíbrio', 'excesso', 'impaciência', 'falta de harmonia', 'extremos']::text[], 'A Temperança fala de equilíbrio conquistado aos poucos, misturando elementos opostos até encontrar harmonia. É tempo de paciência e moderação, integrando partes diferentes da vida de forma gradual e cuidadosa.', 'Invertida, sugere desequilíbrio, excessos ou impaciência diante de um processo que exige tempo. Pode indicar áreas da vida em conflito entre si, pedindo mais moderação e menos extremos.', null, true),
  ('The Devil', 'major', null, 15, ARRAY['apego', 'padrões limitantes', 'tentação', 'materialismo', 'prisão autoimposta']::text[], ARRAY['libertação', 'quebra de padrão', 'consciência do apego', 'recuperação de controle', 'desapego gradual']::text[], 'O Diabo representa amarras que, muitas vezes, são autoimpostas — vícios, padrões repetitivos ou apegos que limitam a liberdade. Convida a olhar com honestidade para o que prende, para começar a se libertar.', 'Invertido, indica o início da libertação de um padrão limitante, ou a consciência crescente sobre algo que prendia. É um passo importante rumo a recuperar o controle sobre as próprias escolhas.', null, true),
  ('The Tower', 'major', null, 16, ARRAY['ruptura súbita', 'revelação', 'colapso de estrutura', 'mudança brusca', 'verdade exposta']::text[], ARRAY['mudança evitada', 'colapso adiado', 'medo da ruptura', 'tensão acumulada', 'resistência à verdade']::text[], 'A Torre fala de uma ruptura repentina que derruba estruturas que já não sustentavam a verdade. Por mais desconfortável que pareça, essa mudança brusca costuma abrir espaço para algo mais autêntico ser reconstruído.', 'Invertida, pode indicar uma ruptura sendo evitada ou adiada, mesmo que a estrutura já esteja fragilizada. A tensão acumulada tende a pedir alívio, ainda que o desconforto de mudar pareça grande.', null, true),
  ('The Star', 'major', null, 17, ARRAY['esperança', 'cura', 'inspiração', 'confiança no futuro', 'renovação serena']::text[], ARRAY['desânimo', 'esperança abalada', 'desconexão com o propósito', 'dúvida', 'cansaço emocional']::text[], 'A Estrela traz esperança depois de um momento difícil, como uma luz serena que orienta o caminho. Fala de cura, inspiração renovada e confiança de que dias melhores estão se formando no horizonte.', 'Invertida, sugere esperança abalada ou desânimo diante de um momento difícil que se prolonga. Pode ser sinal de desconexão com o próprio propósito, pedindo um cuidado mais gentil consigo mesmo.', null, true),
  ('The Moon', 'major', null, 18, ARRAY['intuição', 'incerteza', 'sonhos', 'emoções profundas', 'caminho nebuloso']::text[], ARRAY['confusão dissolvida', 'medos enfrentados', 'clareza gradual', 'iluminação de dúvidas', 'fim da ilusão']::text[], 'A Lua representa um território nebuloso, onde a razão não alcança tudo e a intuição precisa guiar os passos. Fala de emoções profundas, sonhos e uma verdade que ainda não está totalmente clara.', 'Invertida, pode indicar que a confusão começa a se dissolver e a clareza está mais próxima. Também sugere a coragem de enfrentar medos que antes pareciam maiores do que realmente são.', null, true),
  ('The Sun', 'major', null, 19, ARRAY['alegria', 'vitalidade', 'clareza', 'sucesso', 'otimismo genuíno']::text[], ARRAY['otimismo excessivo', 'alegria momentaneamente ofuscada', 'expectativas frustradas', 'energia baixa', 'clareza parcial']::text[], 'O Sol traz vitalidade, alegria genuína e clareza sobre o caminho a seguir. É uma das cartas mais positivas do baralho, indicando sucesso, boas energias e um momento de celebração merecida.', 'Invertido, sugere que a alegria e a clareza ainda estão presentes, mas momentaneamente ofuscadas por expectativas frustradas ou cansaço. Vale buscar pequenas fontes de luz enquanto o brilho pleno não retorna.', null, true),
  ('Judgement', 'major', null, 20, ARRAY['renascimento', 'chamado interior', 'avaliação honesta', 'despertar', 'reconciliação com o passado']::text[], ARRAY['autocrítica dura', 'hesitação diante do chamado', 'dificuldade em perdoar', 'estagnação emocional', 'dúvida sobre o próprio valor']::text[], 'O Julgamento representa um chamado interior para revisar o caminho percorrido e dar um passo de renovação. É tempo de avaliação honesta, aceitando lições do passado para seguir adiante com mais consciência.', 'Invertido, pode indicar dificuldade em ouvir um chamado interior importante, ou autocrítica dura demais diante de erros passados. Perdoar-se pode ser o primeiro passo antes de seguir para a próxima etapa.', null, true),
  ('The World', 'major', null, 21, ARRAY['realização', 'conclusão', 'integração', 'conquista', 'ciclo completo']::text[], ARRAY['conclusão adiada', 'sensação de incompletude', 'últimos ajustes pendentes', 'ciclo não finalizado', 'busca por fechamento']::text[], 'O Mundo representa a conclusão bem-sucedida de um ciclo importante. Fala de realização, integração de aprendizados e a sensação satisfatória de ter percorrido um caminho completo antes de abrir espaço para o próximo.', 'Invertido, sugere que a conclusão de um ciclo está próxima, mas ainda não chegou por completo — faltam ajustes finais. Pode indicar a sensação de incompletude diante de algo quase, mas não totalmente, resolvido.', null, true),
  ('Ace of Wands', 'minor', 'wands', 1, ARRAY['nova energia', 'inspiração', 'impulso criativo', 'potencial de ação', 'entusiasmo']::text[], ARRAY['energia bloqueada', 'falta de direção', 'atraso no início', 'entusiasmo contido', 'ideia não desenvolvida']::text[], 'O Ás de Paus traz uma centelha de energia nova, pronta para se transformar em ação. É o início de um projeto, ideia ou paixão que pede coragem para ser colocada em movimento com entusiasmo genuíno.', 'Invertido, indica energia represada ou um impulso criativo que ainda não encontrou caminho para se expressar. Pode ser hora de identificar o que está bloqueando esse início antes de seguir adiante.', null, true),
  ('Two of Wands', 'minor', 'wands', 2, ARRAY['planejamento', 'visão de futuro', 'expansão', 'decisão estratégica', 'horizonte amplo']::text[], ARRAY['indecisão', 'medo de expandir', 'planos travados', 'insegurança quanto ao futuro', 'hesitação']::text[], 'O Dois de Paus fala de planejamento e visão de futuro, olhando para além do que já é conhecido. É tempo de definir uma direção mais ampla e considerar os próximos passos com estratégia.', 'Invertido, sugere indecisão diante de um plano maior, ou hesitação em dar um passo mais ousado. O medo de sair da zona conhecida pode estar segurando um crescimento que já está pronto para acontecer.', null, true),
  ('Three of Wands', 'minor', 'wands', 3, ARRAY['expansão em curso', 'espera ativa', 'visão de longo prazo', 'progresso', 'colaboração à distância']::text[], ARRAY['atrasos', 'expansão frustrada', 'falta de visão clara', 'obstáculos externos', 'planos estagnados']::text[], 'O Três de Paus mostra planos já em movimento, com resultados começando a se desenhar no horizonte. É tempo de paciência ativa, observando o progresso enquanto se mantém aberto a novas oportunidades.', 'Invertido, pode indicar atrasos em planos que pareciam certos, ou dificuldade em enxergar com clareza os próximos passos. Obstáculos externos podem estar pedindo ajuste de rota ou mais paciência.', null, true),
  ('Four of Wands', 'minor', 'wands', 4, ARRAY['celebração', 'estabilidade', 'conquista compartilhada', 'harmonia doméstica', 'marco importante']::text[], ARRAY['celebração adiada', 'instabilidade momentânea', 'conflito familiar', 'sensação de não pertencer', 'harmonia interrompida']::text[], 'O Quatro de Paus celebra uma conquista alcançada com esforço, muitas vezes ao lado de outras pessoas. Representa estabilidade, harmonia e a alegria de comemorar um marco importante já consolidado.', 'Invertido, sugere que uma celebração ou sensação de estabilidade está sendo adiada, ou que algum conflito está interrompendo a harmonia esperada. Pode indicar também dificuldade em se sentir parte de um grupo.', null, true),
  ('Five of Wands', 'minor', 'wands', 5, ARRAY['competição', 'conflito de ideias', 'tensão criativa', 'disputa', 'diferenças de opinião']::text[], ARRAY['conflito evitado', 'tensão não resolvida', 'competição interna', 'desgaste acumulado', 'necessidade de diálogo']::text[], 'O Cinco de Paus representa competição e conflito de ideias, onde diferentes vontades disputam espaço. Pode ser desgastante, mas também estimula crescimento através do confronto saudável de perspectivas diferentes.', 'Invertido, indica um conflito sendo evitado em vez de enfrentado, o que pode gerar tensão acumulada. Também pode representar disputas internas, pedindo diálogo mais honesto para aliviar o desgaste.', null, true),
  ('Six of Wands', 'minor', 'wands', 6, ARRAY['reconhecimento', 'vitória', 'confiança conquistada', 'sucesso visível', 'orgulho merecido']::text[], ARRAY['reconhecimento adiado', 'insegurança apesar do esforço', 'sucesso não celebrado', 'comparação excessiva', 'dúvida sobre o próprio valor']::text[], 'O Seis de Paus celebra uma vitória reconhecida publicamente, fruto de esforço genuíno. É tempo de aceitar o reconhecimento merecido, com confiança renovada após superar um desafio importante.', 'Invertido, sugere que um reconhecimento esperado ainda não chegou, ou que a pessoa tem dificuldade em celebrar as próprias conquistas. Comparar-se excessivamente com os outros pode estar ofuscando o mérito real.', null, true),
  ('Seven of Wands', 'minor', 'wands', 7, ARRAY['defesa de posição', 'perseverança', 'resistência a pressões', 'firmeza', 'manter-se firme']::text[], ARRAY['exaustão defensiva', 'ceder à pressão', 'insegurança na defesa', 'sobrecarga', 'desistência prematura']::text[], 'O Sete de Paus fala de defender uma posição conquistada diante de desafios ou pressões externas. Pede firmeza e perseverança, mesmo quando parece que é preciso justificar constantemente o próprio espaço.', 'Invertido, pode indicar cansaço de tanto se defender, levando a ceder em algo importante. Também sugere insegurança sobre a própria posição, ou o risco de desistir antes da hora.', null, true),
  ('Eight of Wands', 'minor', 'wands', 8, ARRAY['rapidez', 'movimento acelerado', 'comunicação clara', 'progresso veloz', 'eventos em sequência']::text[], ARRAY['atrasos frustrantes', 'comunicação confusa', 'lentidão inesperada', 'impaciência', 'planos desalinhados']::text[], 'O Oito de Paus indica movimento rápido, com eventos e comunicações acontecendo em sequência acelerada. É tempo de ação ágil, aproveitando o impulso favorável que está se formando no momento.', 'Invertido, sugere atrasos frustrantes ou comunicação que perdeu a clareza. Pode indicar impaciência diante de um ritmo mais lento do que o esperado, exigindo ajuste de expectativas.', null, true),
  ('Nine of Wands', 'minor', 'wands', 9, ARRAY['resiliência', 'última resistência', 'cautela aprendida', 'persistência', 'força após desgaste']::text[], ARRAY['exaustão profunda', 'desistência iminente', 'desconfiança excessiva', 'sobrecarga emocional', 'necessidade de descanso']::text[], 'O Nove de Paus mostra resiliência diante do cansaço, quando já se percorreu um longo caminho difícil. Pede persistência mesmo exausto, confiando que a força reunida até aqui é suficiente para o último esforço.', 'Invertido, indica exaustão profunda ou desconfiança que já passou do ponto saudável. Pode ser sinal de que descansar, mesmo que pareça impossível agora, é mais urgente do que insistir sem pausa.', null, true),
  ('Ten of Wands', 'minor', 'wands', 10, ARRAY['sobrecarga', 'responsabilidade excessiva', 'peso acumulado', 'esforço final', 'carga pesada']::text[], ARRAY['alívio da carga', 'delegação necessária', 'reconhecimento do limite', 'sobrecarga insustentável', 'necessidade de soltar']::text[], 'O Dez de Paus representa o peso de responsabilidades acumuladas, muitas vezes assumidas sozinho. Mostra que se está próximo da meta, mas o esforço para chegar lá pode estar cobrando um preço alto demais.', 'Invertido, sugere a necessidade urgente de soltar parte da carga, seja delegando ou reconhecendo os próprios limites. Continuar carregando tudo sozinho pode estar custando mais do que vale a pena.', null, true),
  ('Page of Wands', 'minor', 'wands', 11, ARRAY['curiosidade', 'entusiasmo iniciante', 'descoberta', 'mensagem inspiradora', 'energia jovem']::text[], ARRAY['entusiasmo disperso', 'imaturidade', 'planos sem direção', 'impulsividade', 'notícia atrasada']::text[], 'O Pajem de Paus traz curiosidade genuína e entusiasmo de quem está descobrindo um novo interesse. Pode representar uma mensagem inspiradora ou o começo animado de um projeto ainda em formação.', 'Invertido, indica entusiasmo que se dispersa antes de amadurecer, ou planos ainda sem direção clara. Também pode sugerir impulsividade sem reflexão suficiente sobre os próximos passos a seguir.', null, true),
  ('Knight of Wands', 'minor', 'wands', 12, ARRAY['ação decidida', 'aventura', 'paixão impulsiva', 'movimento rápido', 'busca por novidade']::text[], ARRAY['impulsividade descontrolada', 'impaciência', 'projetos abandonados', 'agressividade', 'falta de planejamento']::text[], 'O Cavaleiro de Paus age com paixão e decisão, buscando aventura e novidade sem medo de se lançar. Representa energia impulsiva e movimento rápido em direção a algo que desperta entusiasmo genuíno.', 'Invertido, sugere impulsividade sem planejamento, levando a projetos iniciados com empolgação e abandonados cedo demais. Pode também indicar impaciência que se transforma em atritos desnecessários com outras pessoas.', null, true),
  ('Queen of Wands', 'minor', 'wands', 13, ARRAY['confiança magnética', 'independência', 'calor humano', 'determinação serena', 'liderança inspiradora']::text[], ARRAY['insegurança disfarçada', 'autoritarismo', 'ciúme', 'energia dispersa', 'necessidade de validação']::text[], 'A Rainha de Paus une confiança e calor humano, liderando pelo exemplo com determinação serena. Representa independência genuína e a capacidade de inspirar outros através de uma energia autêntica e vibrante.', 'Invertida, pode indicar insegurança escondida atrás de uma postura confiante demais, ou necessidade excessiva de validação externa. Também sugere energia dispersa, precisando de mais foco para se expressar com autenticidade.', null, true),
  ('King of Wands', 'minor', 'wands', 14, ARRAY['liderança visionária', 'carisma', 'ousadia', 'visão estratégica', 'confiança madura']::text[], ARRAY['arrogância', 'impulsividade autoritária', 'visão sem execução', 'impaciência com os outros', 'ambição desmedida']::text[], 'O Rei de Paus lidera com visão, carisma e ousadia madura, inspirando outros a seguir grandes projetos. Representa confiança consolidada e a capacidade de transformar ideias ambiciosas em realizações concretas.', 'Invertido, sugere liderança que se torna autoritária ou impaciente demais com o ritmo alheio. Pode indicar visão grandiosa sem execução prática, ou ambição que perdeu contato com os limites razoáveis.', null, true),
  ('Ace of Cups', 'minor', 'cups', 1, ARRAY['novo amor', 'abertura emocional', 'intuição fluindo', 'conexão genuína', 'coração aberto']::text[], ARRAY['bloqueio emocional', 'coração fechado', 'tristeza contida', 'desconexão afetiva', 'amor não correspondido']::text[], 'O Ás de Copas representa um novo começo emocional, com o coração se abrindo para amor, conexão ou intuição renovada. É um convite para receber afeto genuíno, seja de outra pessoa ou de si mesmo.', 'Invertido, sugere emoções represadas ou dificuldade em se abrir para uma conexão genuína. Pode indicar tristeza contida ou a sensação de que o coração ainda não está pronto para se entregar de novo.', null, true),
  ('Two of Cups', 'minor', 'cups', 2, ARRAY['conexão mútua', 'parceria emocional', 'atração genuína', 'harmonia entre dois', 'reciprocidade']::text[], ARRAY['desequilíbrio afetivo', 'desentendimento', 'conexão unilateral', 'distanciamento', 'confiança abalada']::text[], 'O Dois de Copas fala de conexão mútua e reciprocidade emocional entre duas pessoas. Representa um vínculo equilibrado, seja romântico, de amizade ou parceria, construído sobre respeito e afeto compartilhado.', 'Invertido, indica desequilíbrio em uma relação, com afeto ou esforço não sendo reciprocado da mesma forma. Pode sugerir desentendimentos recentes ou confiança que precisa ser reconstruída com cuidado.', null, true),
  ('Three of Cups', 'minor', 'cups', 3, ARRAY['celebração conjunta', 'amizade', 'alegria compartilhada', 'comunidade', 'momentos de conexão']::text[], ARRAY['isolamento social', 'celebração adiada', 'conflitos entre amigos', 'excessos', 'distanciamento de grupo']::text[], 'O Três de Copas celebra amizade, alegria compartilhada e momentos de conexão genuína com outras pessoas. É tempo de celebrar conquistas ao lado de quem importa, fortalecendo laços através da comunidade.', 'Invertido, sugere isolamento momentâneo ou conflitos dentro de um grupo de amizades. Também pode indicar excessos em uma celebração, ou a sensação de estar distante de uma comunidade que antes acolhia.', null, true),
  ('Four of Cups', 'minor', 'cups', 4, ARRAY['apatia', 'introspecção emocional', 'oportunidade ignorada', 'insatisfação silenciosa', 'reavaliação']::text[], ARRAY['despertar do tédio', 'nova disposição', 'reconexão com desejos', 'saída da estagnação', 'abertura recente']::text[], 'O Quatro de Copas mostra um momento de apatia ou introspecção, onde novas oportunidades podem estar sendo ignoradas. É tempo de reavaliar o que realmente traz satisfação, antes de recusar algo por hábito.', 'Invertido, indica o despertar de um estado de apatia, com disposição renovada para enxergar oportunidades antes ignoradas. Pode representar a reconexão com desejos que estavam adormecidos há algum tempo.', null, true),
  ('Five of Cups', 'minor', 'cups', 5, ARRAY['luto', 'decepção', 'foco no que se perdeu', 'tristeza', 'necessidade de elaborar a dor']::text[], ARRAY['aceitação gradual', 'recomeço emocional', 'perdão', 'olhar para o que resta', 'cura em andamento']::text[], 'O Cinco de Copas representa decepção e luto por algo perdido, com o olhar ainda voltado para o que não deu certo. É importante permitir o processo de tristeza, sem negar a dor sentida.', 'Invertido, sugere que a aceitação está começando a substituir a dor, com o olhar se voltando aos poucos para o que ainda resta. É um sinal de cura emocional em andamento, mesmo que gradual.', null, true),
  ('Six of Cups', 'minor', 'cups', 6, ARRAY['nostalgia', 'memórias afetivas', 'reencontro', 'inocência', 'conexão com o passado']::text[], ARRAY['apego ao passado', 'idealização de memórias', 'dificuldade em seguir em frente', 'saudade excessiva', 'repetição de padrões antigos']::text[], 'O Seis de Copas traz nostalgia e conexão com memórias afetivas, muitas vezes ligadas à infância ou a vínculos antigos. Pode indicar um reencontro significativo ou o resgate de algo simples e genuíno.', 'Invertido, sugere apego excessivo ao passado, dificultando seguir em frente no presente. Pode indicar idealização de memórias ou a repetição de padrões antigos que já não servem mais à vida atual.', null, true),
  ('Seven of Cups', 'minor', 'cups', 7, ARRAY['muitas opções', 'fantasia', 'escolhas difusas', 'sonhos diversos', 'necessidade de foco']::text[], ARRAY['clareza sobre escolhas', 'decisão finalmente tomada', 'fim da confusão', 'foco recuperado', 'realismo']::text[], 'O Sete de Copas mostra um leque de opções e possibilidades, algumas mais realistas que outras. É tempo de discernir entre fantasia e caminho concreto, evitando se perder em sonhos difusos demais.', 'Invertido, indica que a confusão entre tantas opções está se dissipando, trazendo mais clareza sobre qual caminho seguir. Uma decisão que estava adiada pode finalmente estar próxima de se concretizar.', null, true),
  ('Eight of Cups', 'minor', 'cups', 8, ARRAY['afastamento consciente', 'busca por mais sentido', 'deixar para trás', 'jornada interior', 'desapego']::text[], ARRAY['medo de partir', 'estagnação por comodismo', 'retorno a padrões antigos', 'indecisão sobre deixar ir', 'insatisfação prolongada']::text[], 'O Oito de Copas representa a decisão de se afastar de algo que já não satisfaz, em busca de mais sentido. É um desapego consciente, mesmo que doloroso, motivado pela necessidade de crescimento pessoal.', 'Invertido, sugere dificuldade em deixar algo para trás, mesmo sabendo que já não faz sentido continuar. Pode indicar retorno a uma situação antiga por medo do desconhecido, prolongando uma insatisfação conhecida.', null, true),
  ('Nine of Cups', 'minor', 'cups', 9, ARRAY['satisfação', 'realização pessoal', 'gratidão', 'contentamento', 'desejo realizado']::text[], ARRAY['satisfação superficial', 'busca externa por validação', 'insatisfação apesar do sucesso', 'excessos', 'vazio emocional']::text[], 'O Nove de Copas é a carta da satisfação genuína, muitas vezes chamada de carta dos desejos realizados. Representa contentamento emocional e gratidão por conquistas pessoais alcançadas com esforço e presença.', 'Invertido, pode indicar uma satisfação mais superficial do que genuína, ou a busca por validação externa que não preenche de verdade. Vale observar se o contentamento vem de dentro ou só das aparências.', null, true),
  ('Ten of Cups', 'minor', 'cups', 10, ARRAY['harmonia familiar', 'felicidade duradoura', 'conexão emocional plena', 'paz doméstica', 'realização afetiva']::text[], ARRAY['conflitos familiares', 'harmonia aparente', 'desconexão apesar da proximidade', 'expectativas frustradas', 'tensão doméstica']::text[], 'O Dez de Copas representa harmonia emocional plena, muitas vezes ligada à família ou aos vínculos mais próximos. É a sensação de felicidade duradoura, construída sobre conexões verdadeiras e apoio mútuo.', 'Invertido, sugere conflitos dentro de um núcleo próximo, ou uma harmonia que existe mais na aparência do que na prática. Pode indicar expectativas familiares que ainda não foram atendidas de verdade.', null, true),
  ('Page of Cups', 'minor', 'cups', 11, ARRAY['sensibilidade', 'mensagem emocional', 'criatividade intuitiva', 'curiosidade afetiva', 'abertura ao novo sentimento']::text[], ARRAY['imaturidade emocional', 'sensibilidade excessiva', 'mensagem confusa', 'insegurança afetiva', 'criatividade bloqueada']::text[], 'O Pajem de Copas traz sensibilidade e abertura para novas experiências emocionais, muitas vezes através da criatividade ou de uma mensagem inesperada. Representa curiosidade genuína diante dos próprios sentimentos.', 'Invertido, pode indicar sensibilidade excessiva ou dificuldade em lidar com emoções de forma madura. Sugere também uma comunicação pouco clara sobre sentimentos, gerando insegurança na relação com o outro.', null, true),
  ('Knight of Cups', 'minor', 'cups', 12, ARRAY['romantismo', 'convite emocional', 'idealismo', 'busca por conexão', 'gesto afetuoso']::text[], ARRAY['promessas vazias', 'idealização excessiva', 'instabilidade emocional', 'desilusão', 'romantismo superficial']::text[], 'O Cavaleiro de Copas se move guiado pelo coração, trazendo romantismo e um convite genuíno para uma conexão mais profunda. Representa idealismo afetivo e a disposição de se abrir emocionalmente ao novo.', 'Invertido, sugere promessas que não se sustentam ou idealização excessiva de uma pessoa ou situação. Pode indicar instabilidade emocional, com sentimentos que mudam de direção antes de se consolidarem.', null, true),
  ('Queen of Cups', 'minor', 'cups', 13, ARRAY['empatia profunda', 'intuição emocional', 'cuidado genuíno', 'sensibilidade madura', 'acolhimento']::text[], ARRAY['excesso de sensibilidade', 'dependência emocional', 'dificuldade em estabelecer limites', 'absorção emocional alheia', 'insegurança afetiva']::text[], 'A Rainha de Copas representa empatia profunda e intuição emocional madura, capaz de acolher os próprios sentimentos e os dos outros com genuíno cuidado. É a sabedoria de sentir sem se perder no sentimento.', 'Invertida, pode indicar dificuldade em estabelecer limites emocionais, absorvendo demais os sentimentos alheios. Sugere também insegurança afetiva ou uma sensibilidade que, sem equilíbrio, se torna sobrecarga.', null, true),
  ('King of Cups', 'minor', 'cups', 14, ARRAY['equilíbrio emocional', 'sabedoria afetiva', 'compaixão madura', 'estabilidade interior', 'liderança serena']::text[], ARRAY['repressão emocional', 'instabilidade disfarçada', 'manipulação afetiva', 'distanciamento', 'frieza aparente']::text[], 'O Rei de Copas equilibra emoção e razão com maturidade, liderando com compaixão e estabilidade interior. Representa a capacidade de sentir profundamente sem perder a serenidade diante dos desafios da vida.', 'Invertido, pode indicar emoções reprimidas por trás de uma aparência controlada, ou instabilidade afetiva escondida sob frieza. Sugere também a necessidade de reconectar com sentimentos que vêm sendo evitados.', null, true),
  ('Ace of Swords', 'minor', 'swords', 1, ARRAY['clareza mental', 'verdade revelada', 'novo entendimento', 'corte necessário', 'ideia poderosa']::text[], ARRAY['confusão mental', 'verdade distorcida', 'julgamento nublado', 'comunicação truncada', 'clareza perdida']::text[], 'O Ás de Espadas traz clareza mental repentina, como um corte que separa o que é verdadeiro do que é ilusão. Representa uma ideia poderosa ou uma verdade que finalmente se torna visível.', 'Invertido, sugere confusão mental ou uma verdade que está sendo distorcida, seja por si mesmo ou por outra pessoa. Pode indicar dificuldade em pensar com clareza diante de uma decisão importante.', null, true),
  ('Two of Swords', 'minor', 'swords', 2, ARRAY['indecisão', 'impasse', 'escolha evitada', 'equilíbrio tenso', 'necessidade de decidir']::text[], ARRAY['decisão finalmente tomada', 'fim da negação', 'verdade encarada', 'sobrecarga de informação', 'indecisão prolongada']::text[], 'O Dois de Espadas representa um impasse, uma escolha sendo evitada por medo do que a decisão pode revelar. É tempo de reunir coragem para enxergar a situação sem os olhos vendados.', 'Invertido, pode indicar que uma decisão adiada está finalmente sendo enfrentada, ou o oposto: a indecisão se prolongando ainda mais, com informações demais dificultando a escolha necessária.', null, true),
  ('Three of Swords', 'minor', 'swords', 3, ARRAY['dor emocional', 'desilusão', 'mágoa', 'verdade dolorosa', 'coração ferido']::text[], ARRAY['cura emocional', 'perdão em processo', 'dor superada', 'reconciliação', 'alívio gradual']::text[], 'O Três de Espadas representa dor emocional intensa, muitas vezes ligada a uma desilusão ou verdade difícil de aceitar. É importante permitir-se sentir a mágoa, como parte necessária do processo de cura.', 'Invertido, sugere que a dor está começando a ceder espaço para a cura, com perdão e alívio em processo. Pode indicar reconciliação ou o início de uma recuperação emocional mais leve.', null, true),
  ('Four of Swords', 'minor', 'swords', 4, ARRAY['descanso necessário', 'recuperação', 'pausa mental', 'quietude restauradora', 'recolhimento']::text[], ARRAY['descanso adiado', 'esgotamento', 'retorno prematuro à ação', 'inquietação mental', 'necessidade urgente de pausa']::text[], 'O Quatro de Espadas pede uma pausa consciente para recuperação física e mental. É tempo de desacelerar, permitindo que o corpo e a mente descansem antes de retomar qualquer decisão ou esforço.', 'Invertido, indica que o descanso necessário está sendo adiado, levando a um esgotamento maior. Pode ser sinal de retorno precoce à rotina, sem o tempo de recuperação que o momento pedia.', null, true),
  ('Five of Swords', 'minor', 'swords', 5, ARRAY['conflito desgastante', 'vitória vazia', 'tensão nas relações', 'orgulho ferido', 'disputa sem vencedores']::text[], ARRAY['fim do conflito', 'busca por paz', 'reconciliação possível', 'orgulho deixado de lado', 'trégua']::text[], 'O Cinco de Espadas fala de conflitos desgastantes, onde vencer pode custar mais do que vale a pena. Representa tensão nas relações e a necessidade de avaliar se vale a pena continuar disputando.', 'Invertido, sugere o desejo de encerrar um conflito e buscar reconciliação, deixando o orgulho de lado. Pode indicar uma trégua se formando, mesmo que ainda existam mágoas a serem resolvidas.', null, true),
  ('Six of Swords', 'minor', 'swords', 6, ARRAY['transição', 'movimento em direção à calma', 'deixar dificuldades para trás', 'travessia', 'alívio gradual']::text[], ARRAY['dificuldade em avançar', 'resistência à mudança', 'retorno a problemas antigos', 'transição travada', 'estagnação emocional']::text[], 'O Seis de Espadas representa uma transição em direção a águas mais calmas, deixando para trás um período difícil. É um movimento gradual, mas necessário, rumo a mais estabilidade e alívio emocional.', 'Invertido, pode indicar dificuldade em deixar uma situação difícil para trás, com a sensação de estar preso no mesmo lugar. Sugere resistência a uma mudança que, no fundo, já é necessária.', null, true),
  ('Seven of Swords', 'minor', 'swords', 7, ARRAY['estratégia', 'ação discreta', 'necessidade de cautela', 'independência', 'caminho próprio']::text[], ARRAY['verdade exposta', 'consequências de atalhos', 'necessidade de honestidade', 'estratégia revelada', 'confiança abalada']::text[], 'O Sete de Espadas fala de estratégia e ação mais discreta, muitas vezes agindo por conta própria sem envolver todos ao redor. Pode indicar cautela necessária diante de uma situação delicada.', 'Invertido, sugere que uma estratégia discreta pode estar prestes a ser revelada, trazendo consequências. É um chamado para agir com mais honestidade e transparência diante das pessoas envolvidas.', null, true),
  ('Eight of Swords', 'minor', 'swords', 8, ARRAY['sensação de aprisionamento', 'limitação autoimposta', 'medo paralisante', 'pensamentos restritivos', 'sentir-se sem saída']::text[], ARRAY['libertação mental', 'nova perspectiva', 'saída encontrada', 'medo superado', 'clareza sobre opções']::text[], 'O Oito de Espadas representa a sensação de estar preso, muitas vezes por padrões de pensamento limitantes mais do que por uma situação real sem saída. O medo pode estar maior do que os obstáculos de fato.', 'Invertido, indica o início da libertação de pensamentos limitantes, com uma nova perspectiva surgindo sobre a situação. Pode representar a descoberta de que havia mais opções do que se imaginava.', null, true),
  ('Nine of Swords', 'minor', 'swords', 9, ARRAY['ansiedade', 'preocupação noturna', 'medo amplificado', 'angústia mental', 'pensamentos intrusivos']::text[], ARRAY['alívio da ansiedade', 'medo diminuindo', 'pensamentos mais realistas', 'busca por ajuda', 'esperança retornando']::text[], 'O Nove de Espadas fala de ansiedade e preocupações que parecem maiores durante a noite, quando a mente amplifica os medos. É importante buscar apoio e não enfrentar essa angústia sozinho.', 'Invertido, sugere que a ansiedade começa a diminuir, dando espaço para pensamentos mais realistas. Pode indicar a decisão de buscar apoio, o que já traz algum alívio ao peso mental sentido.', null, true),
  ('Ten of Swords', 'minor', 'swords', 10, ARRAY['fim doloroso', 'encerramento', 'ponto de virada', 'exaustão', 'toque de fundo do poço']::text[], ARRAY['recuperação lenta', 'fim do sofrimento', 'resistência em aceitar o fim', 'renovação gradual', 'cicatrização']::text[], 'O Dez de Espadas representa um encerramento doloroso, o fim de um ciclo particularmente difícil. Por mais duro que pareça, essa carta também sugere que, a partir daqui, só resta a possibilidade de recomeçar.', 'Invertido, indica que a recuperação de um período difícil já começou, mesmo que de forma lenta. Pode também sugerir resistência em aceitar que um ciclo específico realmente chegou ao fim.', null, true),
  ('Page of Swords', 'minor', 'swords', 11, ARRAY['curiosidade mental', 'novas ideias', 'comunicação vigilante', 'aprendizado rápido', 'observação atenta']::text[], ARRAY['fofoca', 'informação incompleta', 'impulsividade verbal', 'pensamento disperso', 'comunicação precipitada']::text[], 'O Pajem de Espadas traz curiosidade mental e vontade de aprender algo novo com atenção e agilidade. Pode representar uma notícia inesperada ou o início de uma comunicação importante que exige atenção.', 'Invertido, sugere comunicação precipitada, boatos ou informações incompletas circulando. Pode indicar pensamento disperso, dificultando a concentração necessária para lidar com um assunto que exige mais cuidado.', null, true),
  ('Knight of Swords', 'minor', 'swords', 12, ARRAY['ação rápida', 'determinação mental', 'confronto direto', 'urgência', 'avanço assertivo']::text[], ARRAY['impulsividade agressiva', 'pressa excessiva', 'argumentos mal pensados', 'confronto desnecessário', 'ação precipitada']::text[], 'O Cavaleiro de Espadas age com rapidez e determinação, indo direto ao ponto sem hesitar. Representa urgência e assertividade, mas também a necessidade de equilibrar velocidade com atenção aos detalhes.', 'Invertido, indica pressa excessiva levando a decisões mal pensadas ou confrontos desnecessários. Pode sugerir a necessidade de desacelerar antes de agir, evitando que a urgência comprometa o resultado.', null, true),
  ('Queen of Swords', 'minor', 'swords', 13, ARRAY['clareza racional', 'honestidade direta', 'independência mental', 'discernimento', 'comunicação precisa']::text[], ARRAY['frieza excessiva', 'crítica ácida', 'isolamento emocional', 'rigidez de pensamento', 'distanciamento afetivo']::text[], 'A Rainha de Espadas enxerga com clareza racional, comunicando-se de forma direta e honesta, mesmo quando a verdade é difícil. Representa independência mental e discernimento afiado diante das situações da vida.', 'Invertida, pode indicar honestidade que se torna dura demais, ou frieza usada como proteção emocional. Sugere também rigidez de pensamento, dificultando a abertura para perspectivas diferentes da própria.', null, true),
  ('King of Swords', 'minor', 'swords', 14, ARRAY['autoridade intelectual', 'decisão racional', 'clareza de julgamento', 'liderança justa', 'lógica madura']::text[], ARRAY['autoritarismo frio', 'rigidez excessiva', 'manipulação verbal', 'julgamento tendencioso', 'abuso de poder mental']::text[], 'O Rei de Espadas lidera pela razão e pelo julgamento claro, tomando decisões justas com base em lógica madura. Representa autoridade intelectual e a capacidade de separar fatos de emoções na hora de decidir.', 'Invertido, sugere autoridade exercida de forma fria ou manipuladora, com julgamento que perdeu a imparcialidade. Pode indicar rigidez excessiva, usando a razão para justificar decisões já tomadas emocionalmente.', null, true),
  ('Ace of Pentacles', 'minor', 'pentacles', 1, ARRAY['nova oportunidade material', 'fundação sólida', 'prosperidade em potencial', 'segurança', 'início concreto']::text[], ARRAY['oportunidade perdida', 'insegurança financeira', 'fundação instável', 'atraso material', 'potencial não aproveitado']::text[], 'O Ás de Ouros representa uma nova oportunidade concreta, seja financeira, profissional ou relacionada ao corpo e ao bem-estar. É a semente de algo com potencial real de crescer em segurança e estabilidade.', 'Invertido, sugere uma oportunidade concreta que ainda não se firmou, ou insegurança quanto às bases materiais de um projeto. Pode indicar atraso, mas não necessariamente o fim da possibilidade.', null, true),
  ('Two of Pentacles', 'minor', 'pentacles', 2, ARRAY['equilíbrio de prioridades', 'adaptação', 'malabarismo consciente', 'flexibilidade', 'gestão de recursos']::text[], ARRAY['sobrecarga de tarefas', 'desequilíbrio financeiro', 'dificuldade em priorizar', 'desorganização', 'instabilidade excessiva']::text[], 'O Dois de Ouros fala de equilibrar múltiplas prioridades com flexibilidade e bom humor. Representa a habilidade de se adaptar a mudanças, gerindo tempo e recursos mesmo em meio a alguma instabilidade.', 'Invertido, indica dificuldade em equilibrar demandas simultâneas, levando a desorganização ou desequilíbrio financeiro. Pode ser sinal de que algumas prioridades precisam ser soltas para recuperar estabilidade.', null, true),
  ('Three of Pentacles', 'minor', 'pentacles', 3, ARRAY['trabalho em equipe', 'reconhecimento profissional', 'colaboração', 'habilidade demonstrada', 'construção conjunta']::text[], ARRAY['falta de reconhecimento', 'trabalho em equipe desalinhado', 'colaboração difícil', 'padrões de qualidade não atendidos', 'esforço individual sem apoio']::text[], 'O Três de Ouros representa colaboração e reconhecimento profissional, construído através de trabalho em equipe. É tempo de valorizar contribuições conjuntas e reconhecer a importância de habilidades bem aplicadas.', 'Invertido, sugere dificuldade em colaborar de forma alinhada, ou falta de reconhecimento por um esforço genuíno. Pode indicar padrões de qualidade não atendidos, gerando frustração no ambiente de trabalho.', null, true),
  ('Four of Pentacles', 'minor', 'pentacles', 4, ARRAY['segurança material', 'controle financeiro', 'conservadorismo', 'apego a recursos', 'necessidade de estabilidade']::text[], ARRAY['desapego material', 'generosidade recuperada', 'medo de perder controle', 'abertura a mudanças financeiras', 'flexibilização']::text[], 'O Quatro de Ouros representa a busca por segurança material, às vezes através de controle rígido sobre recursos. Pode indicar prudência saudável ou apego excessivo, dependendo do quanto esse controle já limita outras áreas.', 'Invertido, sugere um movimento de desapego em relação a bens ou controle financeiro rígido. Pode indicar tanto uma generosidade recuperada quanto o medo de perder a segurança que antes parecia garantida.', null, true),
  ('Five of Pentacles', 'minor', 'pentacles', 5, ARRAY['dificuldade material', 'sensação de exclusão', 'preocupação financeira', 'momento difícil', 'busca por apoio']::text[], ARRAY['recuperação gradual', 'fim da escassez', 'apoio encontrado', 'virada financeira', 'esperança renovada']::text[], 'O Cinco de Ouros fala de um momento de dificuldade material ou emocional, com sensação de estar à margem. É importante lembrar que apoio existe, mesmo quando parece difícil enxergá-lo nesse momento.', 'Invertido, indica que um período difícil está começando a se transformar, com apoio surgindo ou uma virada gradual se aproximando. A sensação de escassez começa a dar lugar a mais esperança.', null, true),
  ('Six of Pentacles', 'minor', 'pentacles', 6, ARRAY['generosidade', 'equilíbrio de dar e receber', 'apoio mútuo', 'partilha', 'ajuda genuína']::text[], ARRAY['desequilíbrio de poder', 'ajuda condicionada', 'dependência financeira', 'generosidade interesseira', 'dívida emocional']::text[], 'O Seis de Ouros representa generosidade e equilíbrio entre dar e receber. Pode indicar apoio genuíno sendo oferecido ou recebido, fortalecendo relações através da partilha justa de recursos ou cuidado.', 'Invertido, sugere desequilíbrio na troca entre dar e receber, com ajuda que vem acompanhada de condições. Pode indicar dependência financeira ou emocional que gera desconforto em vez de apoio genuíno.', null, true),
  ('Seven of Pentacles', 'minor', 'pentacles', 7, ARRAY['avaliação de resultados', 'paciência com o crescimento', 'investimento de longo prazo', 'reflexão sobre esforço', 'colheita futura']::text[], ARRAY['impaciência com o progresso', 'esforço sem retorno percebido', 'reavaliação necessária', 'frustração', 'dúvida sobre continuar']::text[], 'O Sete de Ouros pede paciência para avaliar o crescimento de algo que ainda está em desenvolvimento. É tempo de refletir se o esforço investido está no caminho certo, sem pressa por resultados imediatos.', 'Invertido, indica impaciência diante de um progresso mais lento do que o esperado, gerando dúvida sobre continuar investindo esforço ali. Pode ser hora de reavaliar se o caminho ainda faz sentido.', null, true),
  ('Eight of Pentacles', 'minor', 'pentacles', 8, ARRAY['dedicação', 'aprimoramento de habilidades', 'trabalho cuidadoso', 'foco no ofício', 'compromisso com a qualidade']::text[], ARRAY['falta de compromisso', 'trabalho apressado', 'desmotivação', 'perfeccionismo paralisante', 'aprendizado interrompido']::text[], 'O Oito de Ouros representa dedicação ao aprimoramento de uma habilidade, com foco e compromisso genuíno com a qualidade do que se faz. É tempo de investir tempo e atenção no próprio desenvolvimento.', 'Invertido, sugere trabalho feito às pressas ou falta de motivação para continuar aprimorando uma habilidade. Pode indicar perfeccionismo que trava o progresso, ou um aprendizado interrompido antes de amadurecer.', null, true),
  ('Nine of Pentacles', 'minor', 'pentacles', 9, ARRAY['autossuficiência', 'conquista pessoal', 'conforto merecido', 'independência financeira', 'satisfação com o próprio esforço']::text[], ARRAY['dependência inesperada', 'insegurança financeira', 'isolamento excessivo', 'dificuldade em desfrutar conquistas', 'instabilidade material']::text[], 'O Nove de Ouros representa autossuficiência e o conforto de colher os frutos do próprio esforço. É a satisfação de ter construído algo sólido de forma independente, com espaço para desfrutar da conquista.', 'Invertido, pode indicar uma sensação de instabilidade material inesperada, ou dificuldade em aproveitar conquistas já alcançadas. Sugere também isolamento excessivo, mesmo em meio a alguma independência conquistada.', null, true),
  ('Ten of Pentacles', 'minor', 'pentacles', 10, ARRAY['legado', 'estabilidade duradoura', 'riqueza compartilhada', 'segurança familiar', 'prosperidade de longo prazo']::text[], ARRAY['instabilidade familiar', 'disputas sobre herança', 'insegurança de longo prazo', 'valores materiais em conflito', 'fragilidade de estrutura']::text[], 'O Dez de Ouros representa estabilidade duradoura e legado construído ao longo do tempo, muitas vezes envolvendo família ou comunidade. É a sensação de segurança que vai além do momento presente.', 'Invertido, sugere instabilidade em estruturas de longo prazo, possivelmente envolvendo questões financeiras familiares. Pode indicar conflitos sobre valores materiais ou insegurança quanto ao legado que está sendo construído.', null, true),
  ('Page of Pentacles', 'minor', 'pentacles', 11, ARRAY['aprendizado prático', 'novo projeto', 'curiosidade aplicada', 'planejamento cuidadoso', 'primeiros passos concretos']::text[], ARRAY['procrastinação', 'planos sem execução', 'falta de foco prático', 'aprendizado superficial', 'projeto abandonado cedo']::text[], 'O Pajem de Ouros representa curiosidade aplicada ao aprendizado prático, com interesse genuíno em desenvolver um novo projeto ou habilidade. É tempo de dar os primeiros passos concretos com cuidado e dedicação.', 'Invertido, sugere procrastinação diante de um projeto que exige mais dedicação prática. Pode indicar planos que ainda não saíram do papel, ou um aprendizado interrompido antes de gerar resultados concretos.', null, true),
  ('Knight of Pentacles', 'minor', 'pentacles', 12, ARRAY['constância', 'trabalho metódico', 'confiabilidade', 'paciência produtiva', 'compromisso de longo prazo']::text[], ARRAY['estagnação por excesso de cautela', 'teimosia', 'resistência a mudanças necessárias', 'monotonia', 'lentidão excessiva']::text[], 'O Cavaleiro de Ouros avança de forma metódica e confiável, priorizando constância em vez de pressa. Representa compromisso de longo prazo e a paciência necessária para construir resultados sólidos e duradouros.', 'Invertido, pode indicar excesso de cautela levando à estagnação, ou teimosia diante de mudanças que já seriam necessárias. Sugere também rotina que perdeu o propósito, tornando-se monótona demais.', null, true),
  ('Queen of Pentacles', 'minor', 'pentacles', 13, ARRAY['cuidado prático', 'abundância nutritiva', 'equilíbrio entre trabalho e lar', 'generosidade concreta', 'segurança acolhedora']::text[], ARRAY['sobrecarga de cuidados', 'negligência consigo mesma', 'insegurança material', 'desequilíbrio entre lar e trabalho', 'esgotamento prático']::text[], 'A Rainha de Ouros equilibra cuidado prático e abundância, criando um ambiente seguro e acolhedor. Representa generosidade concreta, seja cuidando de pessoas, de um lar ou de projetos com carinho genuíno.', 'Invertida, sugere sobrecarga por cuidar demais dos outros e pouco de si mesma. Pode indicar desequilíbrio entre demandas práticas e bem-estar pessoal, pedindo atenção mais generosa também para as próprias necessidades.', null, true),
  ('King of Pentacles', 'minor', 'pentacles', 14, ARRAY['prosperidade consolidada', 'liderança prática', 'segurança material', 'generosidade estável', 'visão de longo prazo']::text[], ARRAY['materialismo excessivo', 'rigidez financeira', 'apego ao controle', 'generosidade condicionada', 'obsessão por segurança']::text[], 'O Rei de Ouros representa prosperidade consolidada através de esforço constante e visão prática de longo prazo. Lidera com segurança material e generosidade estável, sustentando o que construiu com responsabilidade genuína.', 'Invertido, sugere apego excessivo ao controle financeiro ou materialismo que perdeu equilíbrio com outras áreas da vida. Pode indicar generosidade condicionada, ou uma busca por segurança que se tornou obsessiva.', null, true)
on conflict (canonical_name) do update set
  arcana            = excluded.arcana,
  suit              = excluded.suit,
  card_number       = excluded.card_number,
  upright_keywords  = excluded.upright_keywords,
  reversed_keywords = excluded.reversed_keywords,
  upright_meaning   = excluded.upright_meaning,
  reversed_meaning  = excluded.reversed_meaning,
  image_path        = excluded.image_path,
  active            = excluded.active,
  updated_at        = now();
-- id e created_at nunca são atualizados no conflito — preserva identidade e
-- data de criação original da linha através de reaplicações futuras.


